fragments.old:
/* V2 optional annual membership — How it works/pricing section only. */
.wlm-v2-content #how-it-works .process-pricing-card > h3 { margin-bottom: 12px; }
.wlm-v2-content #how-it-works .membership-intro { margin: 0 0 12px; color: #63516b; font-size: 17px; font-weight: 500; line-height: 1.55; }
.wlm-v2-content #how-it-works .membership-options { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 16px; margin-top: 28px; align-items: stretch; }
.wlm-v2-content #how-it-works .membership-plan { position: relative; min-width: 0; padding: 28px 20px 24px; border: 1px solid rgba(122,30,126,.2); border-radius: 20px; background: #fff; color: var(--ink); font-family: Montserrat, sans-serif; }
.wlm-v2-content #how-it-works .membership-plan-annual { border: 2px solid #7A1E7E; background: linear-gradient(145deg,#fbf3fc,#f1e9f9); box-shadow: 0 10px 24px rgba(61,22,64,.06); }
.wlm-v2-content #how-it-works .membership-plan h4 { min-height: 2.6em; margin: 0 0 10px; color: var(--navy); font-family: Montserrat, sans-serif; font-size: 21px; font-weight: 800; line-height: 1.3; letter-spacing: -.035em; }
.wlm-v2-content #how-it-works .membership-plan-description { min-height: 4.65em; margin: 0 0 18px; color: #63516b; font-size: 15px; font-weight: 500; line-height: 1.55; }
.wlm-v2-content #how-it-works .membership-plan-price { display: flex; align-items: baseline; flex-wrap: wrap; gap: 6px; margin: 0 0 8px; color: var(--teal-dark); }
.wlm-v2-content #how-it-works .membership-plan-price > strong { font-size: clamp(34px,3vw,44px); font-weight: 800; line-height: 1.1; letter-spacing: -.045em; }
.wlm-v2-content #how-it-works .membership-plan-price > span { color: var(--ink); font-size: 15px; font-weight: 650; line-height: 1.4; }
.wlm-v2-content #how-it-works .membership-annual-payment { margin: 0 0 16px; color: #63516b; font-size: 14px; font-weight: 600; line-height: 1.5; }
.wlm-v2-content #how-it-works .membership-plan-benefits { display: grid; gap: 12px; margin: 20px 0 0; padding: 0; list-style: none; }
.wlm-v2-content #how-it-works .membership-plan-benefits > li { display: grid; grid-template-columns: 16px minmax(0,1fr); gap: 8px; min-width: 0; color: var(--ink); font-size: 16px; font-weight: 500; line-height: 1.5; }
.wlm-v2-content #how-it-works .membership-plan-benefits > li > span:first-child { color: var(--teal-dark); font-weight: 800; }
.wlm-v2-content #how-it-works .membership-plan-benefits strong { font-weight: 750; }
.wlm-v2-content #how-it-works .membership-video-regular-price { color: #63516b; font-size: 14px; }
.wlm-v2-content #how-it-works .membership-value-badge { position: absolute; top: -14px; left: 14px; right: 14px; padding: 7px 10px; border-radius: 999px; background: linear-gradient(135deg,#E8339E,#7A1E7E); color: #fff; font-size: 10px; font-weight: 800; line-height: 1.4; letter-spacing: .045em; text-align: center; text-transform: uppercase; }
@media (max-width: 900px) {
  .wlm-v2-content #how-it-works .membership-plan h4 { min-height: 0; }
  .wlm-v2-content #how-it-works .membership-plan-description { min-height: 3.1em; }
}
@media (max-width: 620px) {
  .wlm-v2-content #how-it-works .membership-options { grid-template-columns: minmax(0,1fr); gap: 26px; }
  .wlm-v2-content #how-it-works .membership-plan { padding: 28px 22px 24px; border-radius: 16px; }
  .wlm-v2-content #how-it-works .membership-plan h4 { font-size: 23px; }
  .wlm-v2-content #how-it-works .membership-plan-description { min-height: 0; margin-bottom: 18px; }
  .wlm-v2-content #how-it-works .membership-value-badge { left: 18px; right: auto; max-width: calc(100% - 36px); font-size: 10px; }
}

fragments.new:
/* V2 compact pricing — optional membership benefits disclosure only. */
.wlm-v2-content #how-it-works .compact-member-video,
.wlm-v2-content #how-it-works .compact-annual-unit { display: block; margin-top: 4px; color: #63516b; font-size: 14px; font-weight: 600; line-height: 1.4; letter-spacing: 0; }
.wlm-v2-content #how-it-works .compact-membership-details { min-width: 0; margin-top: 4px; border-bottom: 1px solid rgba(122,30,126,.16); }
.wlm-v2-content #how-it-works .compact-membership-details > summary { display: flex; align-items: center; justify-content: space-between; gap: 12px; min-height: 48px; padding: 12px 0; color: var(--teal-dark); font-family: Montserrat, sans-serif; font-size: 16px; font-weight: 700; line-height: 1.5; cursor: pointer; list-style: none; }
.wlm-v2-content #how-it-works .compact-membership-details > summary::-webkit-details-marker { display: none; }
.wlm-v2-content #how-it-works .compact-membership-details > summary::after { content: none; display: none; }
.wlm-v2-content #how-it-works .compact-membership-details > summary:focus-visible { outline: 3px solid #7A1E7E; outline-offset: 4px; border-radius: 4px; }
.wlm-v2-content #how-it-works .compact-membership-chevron { flex: 0 0 18px; transition: transform 160ms ease; }
.wlm-v2-content #how-it-works .compact-membership-details[open] .compact-membership-chevron { transform: rotate(180deg); }
.wlm-v2-content #how-it-works .compact-membership-benefits { display: grid; gap: 12px; margin: 0; padding: 4px 0 18px; list-style: none; }
.wlm-v2-content #how-it-works .compact-membership-benefits > li { display: grid; grid-template-columns: 16px minmax(0,1fr); gap: 8px; min-width: 0; color: var(--ink); font-family: Montserrat, sans-serif; font-size: 16px; font-weight: 500; line-height: 1.5; }
.wlm-v2-content #how-it-works .compact-membership-benefits > li > span:first-child { color: var(--teal-dark); font-weight: 800; }
.wlm-v2-content #how-it-works .compact-membership-benefits strong { font-weight: 750; }
.wlm-v2-content #how-it-works .process-pricing-card > .process-medication-note { margin: 16px 0 0; }
@media (prefers-reduced-motion: reduce) {
  .wlm-v2-content #how-it-works .compact-membership-chevron { transition: none; }
}
